//! MCP-TOOLS-PP-001: replays the Go `prepare_payment` fixture
//! (`testdata/port/mcp/prepare-payment.json`, generated by
//! `internal/mcp/server/mcp_payment_perplexity_fixture_generator_test.go`)
//! through the native runtime with a fake approval prompt and a recording
//! autotype backend. No keystrokes, dialogs or network are involved.

use serde::Deserialize;
use serde_json::Value;
use std::{
    collections::BTreeMap,
    fs,
    sync::{Arc, Mutex},
};
use symvault_core::platform::{Autotype, PlatformError};
use symvault_core::session::MemoryKeyring;
use symvault_mcp::payment::{DailyTotals, Enforcer, PaymentPolicy};
use symvault_mcp::store_adapter::{ApprovalSeam, StoreReadOnlyRuntime};
use symvault_mcp::{ProtocolHandler, ReadOnlyRuntimeConfig, read_only_tool_names, run_stream};
use symvault_platform::approval::{ApprovalRequest, ApprovalResult, RiskLevel};
use symvault_store::{Entry, Store, audit::RotationConfig};
use tempfile::tempdir;

#[derive(Debug, Deserialize)]
struct Fixture {
    oracle: Oracle,
    server_name: String,
    server_version: String,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Oracle {
    commit_sha: String,
    source_hash: String,
    generator_hash: String,
    go_version: String,
}

#[derive(Debug, Deserialize)]
struct FixtureEntry {
    path: String,
    #[serde(rename = "type")]
    secret_type: String,
    data: BTreeMap<String, Value>,
}

#[derive(Debug, Deserialize)]
struct FixturePolicy {
    instrument: String,
    #[serde(default)]
    allowed_merchants: Vec<String>,
    #[serde(default)]
    per_transaction: String,
    #[serde(default)]
    per_day: String,
    #[serde(default)]
    currency: String,
}

#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    tier: String,
    allowed_paths: Vec<String>,
    approval_mode: String,
    tty: bool,
    #[serde(default)]
    approval_reply: String,
    entries: Vec<FixtureEntry>,
    policy: Option<FixturePolicy>,
    #[serde(default)]
    preseed_total: String,
    #[serde(default)]
    autotype_fail_on: usize,
    observed: Observed,
}

#[derive(Debug, Deserialize)]
struct Observed {
    input: Vec<String>,
    output: Vec<Box<serde_json::value::RawValue>>,
    autotype_calls: Vec<String>,
    approval_reads: usize,
    audit: Vec<AuditEvent>,
    tracker_state: Option<String>,
}

#[derive(Debug, Deserialize, PartialEq, Eq)]
struct AuditEvent {
    action: String,
    #[serde(default)]
    path: String,
    #[serde(default)]
    ok: bool,
}

struct FakeApproval {
    tty: bool,
    reply: String,
    requests: Mutex<Vec<ApprovalRequest>>,
}

impl ApprovalSeam for FakeApproval {
    fn is_tty_present(&self) -> bool {
        self.tty
    }

    fn request(&self, request: &ApprovalRequest) -> ApprovalResult {
        self.requests.lock().unwrap().push(request.clone());
        ApprovalResult {
            approved: matches!(self.reply.as_str(), "y" | "r"),
            // An "r" reply must not be remembered for a CRITICAL operation.
            remembered: self.reply == "r",
            error: None,
        }
    }
}

struct RecordingAutotype {
    typed: Mutex<Vec<String>>,
    fail_on: usize,
}

impl Autotype for RecordingAutotype {
    fn type_text(&self, text: &str) -> Result<(), PlatformError> {
        let mut typed = self.typed.lock().unwrap();
        typed.push(text.to_owned());
        if self.fail_on > 0 && typed.len() == self.fail_on {
            return Err(PlatformError::unavailable("synthetic autotype failure"));
        }
        Ok(())
    }
}

fn today() -> String {
    let now = time::OffsetDateTime::now_utc();
    format!(
        "{:04}-{:02}-{:02}",
        now.year(),
        u8::from(now.month()),
        now.day()
    )
}

#[test]
fn prepare_payment_replays_go_fixture() {
    let fixture: Fixture = serde_json::from_str(include_str!(
        "../../../testdata/port/mcp/prepare-payment.json"
    ))
    .expect("decode actual Go prepare_payment fixture");
    assert_eq!(
        fixture.oracle.commit_sha,
        "1f965f6e56f2507b9183cf30b822f58f7badb951"
    );
    assert_eq!(fixture.oracle.go_version, "go1.26.6");
    assert_eq!(fixture.oracle.source_hash.len(), 64);
    assert_eq!(fixture.oracle.generator_hash.len(), 64);
    assert!(fixture.cases.len() >= 40, "fixture shrank unexpectedly");

    let mut executed_calls = 0_usize;
    for case in fixture.cases {
        let root = tempdir().expect("synthetic disposable vault");
        fs::write(
            root.path().join("config.yaml"),
            "vault:\n  format_version: 1\n",
        )
        .unwrap();
        fs::write(
            root.path().join("identity.age"),
            b"synthetic identity marker",
        )
        .unwrap();
        fs::create_dir(root.path().join("entries")).unwrap();
        let identity = symvault_crypto::generate_identity();
        let store = Store::open(root.path(), &identity).expect("open synthetic store");
        for entry in &case.entries {
            let mut item = Entry {
                path: entry.path.clone(),
                data: entry.data.clone(),
                ..Entry::default()
            };
            item.secret_metadata.secret_type = entry.secret_type.clone();
            store
                .write_new_entry(&entry.path, &item, &identity)
                .unwrap_or_else(|error| panic!("{}: seed {}: {error}", case.name, entry.path));
        }

        let state_dir = tempdir().expect("payment state dir");
        let state_path = state_dir.path().join("state").join("daily-totals.json");
        let enforcer = case.policy.as_ref().map(|policy| {
            if !case.preseed_total.is_empty() {
                fs::create_dir_all(state_path.parent().unwrap()).unwrap();
                fs::write(
                    &state_path,
                    format!(
                        "{{\"entries\":{{{:?}:{{{:?}:{:?}}}}}}}",
                        policy.instrument,
                        today(),
                        case.preseed_total
                    ),
                )
                .unwrap();
            }
            Enforcer::from_file(
                PaymentPolicy {
                    instrument: policy.instrument.clone(),
                    allowed_merchants: policy.allowed_merchants.clone(),
                    max_amount: symvault_mcp::payment::PaymentMaxAmount {
                        per_transaction: policy.per_transaction.clone(),
                        per_day: policy.per_day.clone(),
                    },
                    currency: policy.currency.clone(),
                },
                &state_path,
            )
            .expect("load payment tracker")
        });

        let audit = symvault_store::audit::open_with_keyring(
            "pp-fixture",
            root.path(),
            &MemoryKeyring::new(),
            RotationConfig::default(),
        )
        .expect("open synthetic audit logger");
        let audit_path = audit.path().to_owned();
        let approval = Arc::new(FakeApproval {
            tty: case.tty,
            reply: case.approval_reply.clone(),
            requests: Mutex::new(Vec::new()),
        });
        let autotype = Arc::new(RecordingAutotype {
            typed: Mutex::new(Vec::new()),
            fail_on: case.autotype_fail_on,
        });
        let mut tools = read_only_tool_names();
        tools.extend(["prepare_payment".to_owned()]);
        let runtime = StoreReadOnlyRuntime::from_store_with_audit(
            store,
            identity,
            ReadOnlyRuntimeConfig {
                server_name: fixture.server_name.clone(),
                server_version: fixture.server_version.clone(),
                transport: "stdio".into(),
                agent_name: "pp-fixture".into(),
                tier: case.tier.clone(),
                allowed_paths: case.allowed_paths.clone(),
                approval_mode: case.approval_mode.clone(),
                available_tools: tools,
                vault_dir: "<fixture-vault>".into(),
                vault_unlocked: true,
                ..ReadOnlyRuntimeConfig::default()
            },
            None,
            Some(Arc::new(Mutex::new(audit))),
        )
        .expect("construct synthetic runtime")
        .with_approval_seam(approval.clone())
        .with_payment_enforcer(enforcer)
        .with_autotype(autotype.clone());
        let mut handler = ProtocolHandler::with_tool_call_runtime(
            &fixture.server_name,
            &fixture.server_version,
            Arc::new(runtime),
        );
        let input = case
            .observed
            .input
            .iter()
            .map(|line| format!("{line}\n"))
            .collect::<String>();
        let lines =
            run_stream(&input, &mut handler).expect("Rust prepare_payment protocol dispatch");
        let actual: Vec<Value> = lines
            .iter()
            .map(|line| serde_json::from_str(line).expect("Rust response is JSON"))
            .collect();
        assert_eq!(
            lines.len(),
            case.observed.output.len(),
            "frame count for {}",
            case.name
        );
        // Byte-exact. The fixture is pretty-printed, so Go's frames are
        // re-compacted; Go's `<`/`>`/`&` escaping is preserved by compact.
        for (index, (got, want)) in lines.iter().zip(&case.observed.output).enumerate() {
            assert_eq!(
                got,
                &symvault_gojson::compact(want.get()),
                "response frame {index} for {}",
                case.name
            );
        }
        executed_calls += case.observed.input.len() - 2;

        let rendered = serde_json::to_string(&actual).unwrap();
        for secret in ["4111111111111111", "DE89370400440532013000"] {
            assert!(
                !rendered.contains(secret),
                "{} leaked a payment value",
                case.name
            );
        }

        assert_eq!(
            *autotype.typed.lock().unwrap(),
            case.observed.autotype_calls,
            "autotype calls for {}",
            case.name
        );

        let requests = approval.requests.lock().unwrap();
        assert_eq!(
            requests.len(),
            case.observed.approval_reads,
            "approval prompts for {}",
            case.name
        );
        for request in requests.iter() {
            assert_eq!(request.operation, "prepare_payment");
            assert_eq!(request.risk_level, RiskLevel::Critical);
            assert!(
                !request.can_remember,
                "CRITICAL approvals cannot be remembered"
            );
            assert!(
                request
                    .details
                    .starts_with("Allow payment of EUR 75.00 to shop.example?"),
                "approval summary for {}: {:?}",
                case.name,
                request.details
            );
        }
        if case.name == "approval_prompt_approved_with_description" {
            assert_eq!(
                requests[0].details,
                "Allow payment of EUR 75.00 to shop.example?\nDescription: order #42 <test> & more"
            );
        }
        if case.name == "approval_prompt_remember_reply_is_not_remembered" {
            let counters: Vec<i64> = requests.iter().map(|r| r.secrets_accessed).collect();
            assert_eq!(counters, [0, 1], "approval counter increments per grant");
        }
        drop(requests);

        let audit_text = fs::read_to_string(&audit_path).unwrap_or_default();
        let actual_audit: Vec<AuditEvent> = audit_text
            .lines()
            .filter(|line| !line.is_empty())
            .map(|line| serde_json::from_str(line).expect("audit line is JSON"))
            .collect();
        assert_eq!(
            actual_audit, case.observed.audit,
            "audit trail for {}",
            case.name
        );

        let tracker = fs::read_to_string(&state_path)
            .ok()
            .map(|state| state.replace(&today(), "<today>"));
        // Pre-seeded state is compact JSON authored by the test, and Go leaves
        // it untouched on denial; every other state file is Go-formatted.
        assert_eq!(
            tracker, case.observed.tracker_state,
            "tracker bytes for {}",
            case.name
        );
    }
    assert!(
        executed_calls >= 50,
        "too few tools/call frames executed: {executed_calls}"
    );
}

#[test]
fn tracker_matches_go_unit_vectors() {
    let directory = tempdir().unwrap();
    let path = directory
        .path()
        .join("sub")
        .join("dir")
        .join("daily-totals.json");
    let mut tracker = DailyTotals::load(&path).unwrap();
    assert_eq!(tracker.today_total("policy-a"), "0");
    tracker.add_to_today("policy-a", "25.50").unwrap();
    assert_eq!(tracker.today_total("policy-a"), "51/2");
    tracker.add_to_today("policy-a", "10.25").unwrap();
    assert_eq!(tracker.today_total("policy-a"), "143/4");

    let reloaded = DailyTotals::load(&path).unwrap();
    assert_eq!(reloaded.today_total("policy-a"), "143/4");

    // Yesterday's entries expire on load, and a corrupt file is an error.
    let expired = directory.path().join("expired.json");
    fs::write(
        &expired,
        r#"{"entries":{"policy-a":{"2000-01-01":"100.00"}}}"#,
    )
    .unwrap();
    assert_eq!(
        DailyTotals::load(&expired).unwrap().today_total("policy-a"),
        "0"
    );
    let corrupt = directory.path().join("corrupt.json");
    fs::write(&corrupt, "{not json").unwrap();
    assert!(DailyTotals::load(&corrupt).is_err());
    assert!(
        Enforcer::from_file(PaymentPolicy::default(), &corrupt).is_err(),
        "Go leaves a corrupt tracker without an enforcer (fail-open) - the loader reports it"
    );

    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let file_mode = fs::metadata(&path).unwrap().permissions().mode() & 0o777;
        let dir_mode = fs::metadata(path.parent().unwrap())
            .unwrap()
            .permissions()
            .mode()
            & 0o777;
        assert_eq!((file_mode, dir_mode), (0o600, 0o700));
    }
    let text = fs::read_to_string(&path).unwrap();
    assert!(text.starts_with("{\n  \"entries\": {\n    \"policy-a\": {\n      \""));
    assert!(text.ends_with("\": \"143/4\"\n    }\n  }\n}"));
}
